import pandas as pd
import numpy as np


TARGET_COLUMN = 'target'


class DecisionTree:
    """Simple CART decision tree for binary classification."""

    def __init__(self, max_depth=6, min_samples_split=20):
        self.max_depth = max_depth
        self.min_samples_split = min_samples_split
        self.tree = None

    def _gini(self, y):
        n = len(y)
        if n == 0:
            return 0.0
        p = y.mean()
        return 2 * p * (1 - p)

    def _best_split(self, X, y):
        n, d = X.shape
        best_gain = 0.0
        best_feat = -1
        best_thresh = 0.0
        base_gini = self._gini(y)

        for feat in range(d):
            vals = X[:, feat]
            # Use percentiles as candidate thresholds
            thresholds = np.percentile(vals, np.linspace(10, 90, 10))
            thresholds = np.unique(thresholds)
            for thresh in thresholds:
                left_mask = vals <= thresh
                right_mask = ~left_mask
                nl = left_mask.sum()
                nr = right_mask.sum()
                if nl < self.min_samples_split or nr < self.min_samples_split:
                    continue
                gain = base_gini - (nl * self._gini(y[left_mask]) + nr * self._gini(y[right_mask])) / n
                if gain > best_gain:
                    best_gain = gain
                    best_feat = feat
                    best_thresh = thresh
        return best_feat, best_thresh, best_gain

    def _build(self, X, y, depth):
        if depth >= self.max_depth or len(y) < self.min_samples_split:
            return {'leaf': True, 'val': int(y.mean() >= 0.5)}
        feat, thresh, gain = self._best_split(X, y)
        if gain <= 0 or feat == -1:
            return {'leaf': True, 'val': int(y.mean() >= 0.5)}
        mask = X[:, feat] <= thresh
        left = self._build(X[mask], y[mask], depth + 1)
        right = self._build(X[~mask], y[~mask], depth + 1)
        return {'leaf': False, 'feat': feat, 'thresh': thresh, 'left': left, 'right': right}

    def fit(self, X, y):
        self.tree = self._build(X, y, 0)
        return self

    def _predict_one(self, x, node):
        if node['leaf']:
            return node['val']
        if x[node['feat']] <= node['thresh']:
            return self._predict_one(x, node['left'])
        else:
            return self._predict_one(x, node['right'])

    def predict(self, X):
        return np.array([self._predict_one(x, self.tree) for x in X])


def predict(train_csv: str, test_csv: str, output_csv: str) -> None:
    """Train a decision tree and predict test labels."""
    train = pd.read_csv(train_csv)
    test = pd.read_csv(test_csv)

    feature_cols = [c for c in train.columns if c != TARGET_COLUMN]
    X_train = train[feature_cols].to_numpy()
    y_train = train[TARGET_COLUMN].to_numpy().astype(float)
    X_test = test[feature_cols].to_numpy()

    tree = DecisionTree(max_depth=10, min_samples_split=100)
    tree.fit(X_train, y_train)
    preds = tree.predict(X_test)

    predictions = pd.DataFrame({"prediction": preds})
    predictions.to_csv(output_csv, index=False)

